// ===== نمایش نتیجه: جدول Markdown + نمودار (تصویر QuickChart بر پایه‌ی Chart.js) =====
const AUTO_CHART = true;   // نمودار بدون درخواست صریح کاربر هم کشیده شود
const MAX_TABLE  = 50;     // حداکثر ردیف نمایشی در جدول
const MAX_CHART  = 20;     // سقف تعداد نقطه در نمودار (بر اساس نوع نمودار پایین‌تر می‌آید)

// کدام Security اجرا شده: مسیر اصلی یا مسیر retry بعد از خطای اجرای SQL
let secData;
try { secData = $('Retry: Security').first().json; } catch (e) {
  try { secData = $('Security').first().json; } catch (e2) { secData = {}; }
}
const thinking = (secData.thinking || '').trim();
const thinkBlock = thinking ? `<think>\n${thinking}\n</think>\n\n` : '';

const rows = $input.all().map(i => i.json);
if (rows.length === 0) {
  return [{ json: { answer: thinkBlock + 'نتیجه‌ای یافت نشد.' } }];
}

const question = $('Webhook').first().json.body.question || '';
const cols = Object.keys(rows[0]);

// ---------- کمکی‌ها ----------
const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).trim().replace(/,/g, '');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
};

const fmtCell = v => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number') {
    return Number.isInteger(v) ? v.toLocaleString('en-US')
                               : v.toLocaleString('en-US', { maximumFractionDigits: 2 });
  }
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) return s.slice(0, 10);
  return s;
};

// ---------- جدول ----------
const shown = rows.slice(0, MAX_TABLE);
let md = '| ' + cols.join(' | ') + ' |\n';
md += '| ' + cols.map(() => '---').join(' | ') + ' |\n';
for (const r of shown) md += '| ' + cols.map(c => fmtCell(r[c])).join(' | ') + ' |\n';
if (rows.length > shown.length) {
  md += `\n_${rows.length} ردیف یافت شد، ${shown.length} ردیف اول نمایش داده شده._\n`;
}

// ---------- تشخیص ستون اندازه و برچسب ----------
const numericCols = cols.filter(c => rows.some(r => toNum(r[c]) !== null)
                                  && rows.every(r => r[c] === null || toNum(r[c]) !== null));
const valueCol = numericCols.length ? numericCols[numericCols.length - 1] : null;
const labelCols = cols.filter(c => c !== valueCol).slice(0, 3);
const isTemporal = labelCols.some(c =>
  /date|month|year|day|quarter|week|period|تاریخ|ماه|سال|روز|فصل|هفته|دوره/i.test(c));

// ---------- انتخاب نوع نمودار ----------
let type = null;
if (/دایره|پای|کیک|سهم|\bpie\b/i.test(question))               type = 'pie';
else if (/خطی|روند|تغییرات|\btrend\b|\bline\b/i.test(question)) type = 'line';
else if (/میله|ستون|\bbar\b|\bcolumn\b/i.test(question))        type = 'bar';
else if (/نمودار|چارت|\bchart\b|\bgraph\b|رسم/i.test(question) || AUTO_CHART) {
  if (isTemporal)            type = 'line';
  else if (rows.length <= 6) type = 'pie';
  else                       type = 'bar';
}

const CHART_LIMITS = { pie: 8, line: 15, bar: 20 };
const chartCap = Math.min(MAX_CHART, CHART_LIMITS[type] || MAX_CHART);

// پالت رنگ برای اینکه هر میله/برش رنگ خودش را داشته باشد، نه یک رنگ یکنواخت
const PALETTE = ['#4E79A7','#F28E2B','#E15759','#76B7B2','#59A14F','#EDC948',
                  '#B07AA1','#FF9DA7','#9C755F','#BAB0AC','#86BCB6','#D37295'];
const colorAt = i => PALETTE[i % PALETTE.length];

let chartImageUrl = '';
let chartTitle = '';

if (type && valueCol && labelCols.length && rows.length >= 2) {
  const clean = v => String(v ?? '').replace(/[\[\],;]/g, ' ').replace(/\s+/g, ' ').trim();
  const safeTitle = v => clean(String(v ?? '').replace(/[:]/g, ' ')).slice(0, 70);

  let data = rows.map(r => ({
    // برچسب کامل نگه داشته می‌شود؛ Chart.js خودش فضای لازم را برای آن رزرو می‌کند
    label: labelCols.map(c => clean(fmtCell(r[c]))).filter(Boolean).join(' ').slice(0, 40),
    value: Math.round((toNum(r[valueCol]) ?? 0) * 100) / 100
  })).filter(d => d.label);

  data = data.slice(0, chartCap); // ترتیب از ORDER BY کوئری می‌آید؛ دوباره مرتب نمی‌کنیم

  // برچسب تکراری یعنی هر ردیف یک نقطه‌ی مستقل نیست
  if (new Set(data.map(d => d.label)).size !== data.length) data = [];

  const title = safeTitle(question) || safeTitle(`${valueCol} بر اساس ${labelCols.join(' و ')}`);
  chartTitle = title;

  if (data.length >= 2) {
    const labels = data.map(d => d.label);
    const values = data.map(d => d.value);

    // میله افقی وقتی برچسب‌ها طولانی یا تعدادشان زیاد است خواناتر است
    const avgLabelLen = labels.reduce((s, l) => s + l.length, 0) / labels.length;
    const horizontal = type === 'bar' && (data.length > 8 || avgLabelLen > 14);

    let config, width, height;

    if (type === 'pie') {
      const positive = data.filter(d => d.value > 0);
      if (positive.length >= 2) {
        config = {
          type: 'pie',
          data: {
            labels: positive.map(d => d.label),
            datasets: [{ data: positive.map(d => d.value),
                         backgroundColor: positive.map((_, i) => colorAt(i)) }]
          },
          options: {
            plugins: {
              title: { display: true, text: title, font: { size: 18 } },
              legend: { position: 'right', labels: { font: { size: 13 } } }
            }
          }
        };
        width = 640; height = 480;
      }
    } else if (type === 'line') {
      config = {
        type: 'line',
        data: {
          labels,
          datasets: [{
            label: safeTitle(valueCol),
            data: values,
            borderColor: colorAt(0),
            backgroundColor: colorAt(0),
            pointBackgroundColor: labels.map((_, i) => colorAt(i)),
            pointRadius: 4,
            tension: 0.25,
            fill: false
          }]
        },
        options: {
          plugins: {
            title: { display: true, text: title, font: { size: 18 } },
            legend: { display: false }
          },
          scales: {
            x: { ticks: { font: { size: 13 } } },
            y: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true }
          }
        }
      };
      width = Math.min(1200, Math.max(650, data.length * 70));
      height = 460;
    } else { // bar
      config = {
        type: 'bar',
        data: {
          labels,
          datasets: [{
            label: safeTitle(valueCol),
            data: values,
            backgroundColor: labels.map((_, i) => colorAt(i)),
            borderRadius: 4
          }]
        },
        options: {
          indexAxis: horizontal ? 'y' : 'x',
          plugins: {
            title: { display: true, text: title, font: { size: 18 } },
            legend: { display: false }
          },
          scales: horizontal
            ? { x: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true },
                y: { ticks: { autoSkip: false, font: { size: 13 } } } }
            : { x: { ticks: { font: { size: 12 } } },
                y: { title: { display: true, text: safeTitle(valueCol) }, beginAtZero: true } }
        }
      };
      if (horizontal) {
        width  = 760;
        height = Math.min(1200, Math.max(420, data.length * 38 + 110)); // فضای کافی برای هر ردیف برچسب
      } else {
        width  = Math.min(1300, Math.max(650, data.length * 80));
        height = 460;
      }
    }

    if (config) {
      // URLSearchParams در sandbox نود Code موجود نیست؛ کوئری‌استرینگ را دستی می‌سازیم
      const qcParams = {
        c: JSON.stringify(config),
        w: String(width),
        h: String(height),
        backgroundColor: 'white',
        version: '4',
        devicePixelRatio: '2'
      };
      const qs = Object.entries(qcParams)
        .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
        .join('&');
      chartImageUrl = `http://localhost:3001/chart?${qs}`;
    }
  }
}

if (rows.length > chartCap && type) {
  md += `\n_نمودار برای خوانایی بیشتر به ${chartCap} ردیف اول محدود شده است (از مجموع ${rows.length} ردیف)._\n`;
}

const chartMd = chartImageUrl ? `\n![${chartTitle}](${chartImageUrl})\n` : '';
const answer = thinkBlock + md + chartMd;
return [{ json: { answer } }];

const rows = $input.all();
const rowCount = rows.length;

const username = $('AuthCheck').first().json.username || 'unknown';
const question = $('Webhook').first().json.body.question || '';

let secData, attempt;
try { secData = $('Retry: Security').first().json; attempt = 2; } catch (e) {
  secData = $('Security').first().json; attempt = 1;
}

return [{
  json: {
    username: username,
    question: question,
    generated_sql: secData.sql || '',
    understood_query: secData.understood || '',
    thinking: secData.thinking || '',
    attempt: attempt,
    status: 'SUCCESS',
    row_count: rowCount
  }
}];

// ===== ۱. استخراج متن پاسخ از API =====
const res = $input.first().json;

let raw = '';
if (typeof res === 'string') {
  raw = res;
} else {
  const KEYS = ['result','response','answer','text','output','message','content'];
  for (const k of KEYS) {
    if (typeof res[k] === 'string' && res[k].trim()) { raw = res[k]; break; }
  }
  if (!raw) {
    const s = Object.values(res).find(v => typeof v === 'string' && v.trim().length > 5);
    if (s) raw = s;
  }
}
if (!raw) {
  throw new Error('⛔ ساختار پاسخ API شناخته نشد: ' + JSON.stringify(res).slice(0, 300));
}

// ===== ۱ب. جدا کردن reasoning/thinking مدل (برای نمایش در OpenWebUI) =====
let thinking = '';
if (typeof res === 'object' && res) {
  const THINK_KEYS = ['thinking', 'reasoning', 'reasoning_content', 'thoughts'];
  for (const k of THINK_KEYS) {
    if (typeof res[k] === 'string' && res[k].trim()) { thinking += res[k].trim() + '\n'; break; }
  }
}
const thinkTag = raw.match(/<think>([\s\S]*?)<\/think>/i);
if (thinkTag) {
  thinking += thinkTag[1].trim();
  raw = raw.replace(thinkTag[0], '').trim();
}

// ===== ۱ج. جدا کردن پاکت ساختاریافته: UNDERSTOOD: ... / SQL: ... =====
let understood = '';
const understoodMatch = raw.match(/UNDERSTOOD:\s*(.+)/i);
if (understoodMatch) understood = understoodMatch[1].trim();

const sqlMarker = raw.search(/\bSQL:\s*/i);
if (sqlMarker !== -1) {
  const leftover = raw.slice(0, sqlMarker).replace(/UNDERSTOOD:.*$/im, '').trim();
  if (leftover) thinking = (thinking ? thinking + '\n' : '') + leftover;
  raw = raw.slice(sqlMarker).replace(/^SQL:\s*/i, '').trim();
} else if (understoodMatch) {
  raw = raw.replace(understoodMatch[0], '').trim();
}

// ===== ۲. جدا کردن SQL از متن پرحرف مدل (فالبک قبلی، بدون تغییر) =====
let sql = '';
const fence = raw.match(/```sql\s*([\s\S]*?)```/i) || raw.match(/```\s*([\s\S]*?)```/);
if (fence) {
  sql = fence[1].trim();
} else {
  const m = raw.match(/\b(select|with)\b[\s\S]*/i);
  sql = m ? m[0].trim() : raw.trim();
  sql = sql.split(/\n\s*\n/)[0].trim();
}

const SQLKW = /^\s*(select|from|where|group|order|having|join|inner|left|right|full|cross|outer|on|and|or|union|with|as|top|case|when|then|else|end|\)|,)/i;
sql = sql.split('\n')
         .filter(l => !/[؀-ۿ]/.test(l) || SQLKW.test(l) || l.includes("'"))
         .join('\n').trim();

sql = sql.replace(/;+\s*$/, '').trim();
if (!sql) {
  throw new Error('⛔ مدل نتوانست کوئری تولید کند. لطفاً سوال را واضح‌تر بپرسید.');
}

// ===== ۳. تور ایمنی: LIMIT n → TOP n =====
const lim = sql.match(/\blimit\s+(\d+)\s*;?\s*$/i);
if (lim) {
  sql = sql.replace(/\blimit\s+\d+\s*;?\s*$/i, '').trim();
  if (!/^\s*select\s+top\b/i.test(sql)) {
    sql = sql.replace(/^\s*select\b/i, `SELECT TOP ${lim[1]}`);
  }
}

// ===== ۴. لایه امنیتی =====
if (!/^\s*(select|with)\b/i.test(sql)) {
  throw new Error('⛔ عملیات مجاز نیست: فقط SELECT.');
}
const blocked = [
  /\binsert\b/i, /\bupdate\b/i, /\bdelete\b/i, /\bdrop\b/i,
  /\btruncate\b/i, /\balter\b/i, /\bcreate\b/i, /\bmerge\b/i,
  /\bexec\b/i, /\bexecute\b/i, /\bgrant\b/i, /\brevoke\b/i,
  /\bbackup\b/i, /\brestore\b/i, /\bshutdown\b/i, /\bwaitfor\b/i,
  /\binto\b/i, /\bxp_\w+/i, /\bsp_\w+/i, /openrowset/i, /opendatasource/i,
  // اصلاح امنیتی ۴: DBCC می‌تواند دستورات مدیریتی/DoS اجرا کند؛
  // APPLY می‌تواند توابع دلخواه (خارج از کاتالوگ) را صدا بزند - هر دو مسدود می‌شوند
  /\bdbcc\b/i, /\bapply\b/i, /\bopenxml\b/i
];
for (const p of blocked) {
  if (p.test(sql)) throw new Error('⛔ عملیات مجاز نیست: دستور غیرمجاز.');
}
if (sql.includes(';') || sql.includes('--') || sql.includes('/*')) {
  throw new Error('⛔ عملیات مجاز نیست: کاراکتر غیرمجاز.');
}

// اصلاح امنیتی ۲: JOIN با کاما (implicit join) از رجکس بررسی موجودیت‌ها فرار می‌کند
// چون فقط دنبال FROM/JOIN می‌گردد، نه کاما. این تابع هر FROM را تا اولین بند مرزی
// (در همان عمق پرانتز) اسکن می‌کند و اگر کاما دید، کوئری را رد می‌کند.
function hasImplicitCommaJoin(s) {
  const boundaryRe = /^\s*(where|group\s+by|order\s+by|having|union|except|intersect|for\b)\b/i;
  const fromRe = /\bfrom\b/gi;
  let m;
  while ((m = fromRe.exec(s)) !== null) {
    let i = m.index + m[0].length;
    let depth = 0, quote = null;
    while (i < s.length) {
      const ch = s[i];
      if (quote) { if (ch === quote) quote = null; i++; continue; }
      if (ch === "'" || ch === '"') { quote = ch; i++; continue; }
      if (ch === '[') { const e = s.indexOf(']', i); i = (e === -1 ? s.length : e + 1); continue; }
      if (ch === '(') { depth++; i++; continue; }
      if (ch === ')') { if (depth === 0) break; depth--; i++; continue; }
      if (depth === 0) {
        if (ch === ',') return true;
        if (boundaryRe.test(s.slice(i))) break;
      }
      i++;
    }
  }
  return false;
}
if (hasImplicitCommaJoin(sql)) {
  throw new Error('⛔ فقط سینتکس JOIN صریح مجاز است (نه کاما در FROM).');
}

// ===== ۵. سقف ردیف اجباری =====
function injectTop(s, n) {
  if (/^\s*select\s+top\b/i.test(s)) return s;
  if (/^\s*select\b/i.test(s)) return s.replace(/^\s*select\b/i, `SELECT TOP ${n}`);
  let depth = 0, quote = null;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === quote) quote = null; continue; }
    if (ch === "'" || ch === '"') { quote = ch; continue; }
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (depth === 0 && (ch === 's' || ch === 'S') && /^select\b/i.test(s.slice(i))) {
      const before = i === 0 ? ' ' : s[i - 1];
      if (/[A-Za-z0-9_\]]/.test(before)) continue;
      if (/^select\s+top\b/i.test(s.slice(i))) return s;
      return s.slice(0, i) + `SELECT TOP ${n}` + s.slice(i + 6);
    }
  }
  return s;
}
sql = injectTop(sql, 200);

// ===== ۶. اعتبارسنجی: فقط موجودیت‌های انتخاب‌شده =====
const defs = $('BuildPrompt').first().json.entityDefs || {};
const allowedNames = new Set(Object.keys(defs).map(n => n.toLowerCase()));

// اصلاح امنیتی ۳: پشتیبانی از شناسه‌های داخل گیومه "..." علاوه بر [...]
// (رجکس قبلی فقط [نام] یا نام‌ ساده را می‌شناخت و نام‌های "..." را کاملاً نادیده می‌گرفت)
const IDENT = '(?:\\[[^\\]]+\\]|"[^"]+"|[A-Za-z0-9_]+)';
const stripQuotes = t => t.replace(/^\[|\]$/g, '').replace(/^"|"$/g, '');

const cteNames = new Set();
const cteRe = new RegExp(`(?:\\bwith\\b|,)\\s*(${IDENT})\\s+as\\s*\\(`, 'gi');
let cm;
while ((cm = cteRe.exec(sql)) !== null) cteNames.add(stripQuotes(cm[1]).toLowerCase());

// اصلاح امنیتی ۱: اگر مدل نام یک CTE را برابر با یک موجودیت واقعی کاتالوگ تعریف کند،
// می‌تواند آن موجودیت را با منبع دلخواه خودش جایگزین (shadow) کند و کل کنترل دسترسی
// را دور بزند. به‌جای رد شدن بی‌سروصدا از این حالت، صراحتاً آن را مسدود می‌کنیم.
for (const cn of cteNames) {
  if (allowedNames.has(cn)) {
    throw new Error('⛔ نام‌گذاری غیرمجاز: نام CTE با یک موجودیت کاتالوگ تداخل دارد.');
  }
}

const referenced = new Set();
const refRe = new RegExp(`\\b(?:from|join)\\s+(${IDENT}(?:\\.${IDENT}){0,2})`, 'gi');
let mm;
while ((mm = refRe.exec(sql)) !== null) {
  const parts = mm[1].split('.');
  const nm = stripQuotes(parts[parts.length - 1]).toLowerCase();
  if (cteNames.has(nm)) continue; // CTE واقعی و بی‌ضرر خود مدل (دیگر نمی‌تواند نام کاتالوگ را بدزدد)
  if (!allowedNames.has(nm)) {
    throw new Error('⛔ اجرای این دستور خارج از حیطه دسترسی شماست.');
  }
  referenced.add(nm);
}

if (referenced.size === 0) {
  throw new Error('⛔ کوئری تولیدشده به هیچ موجودیت معتبری ارجاع ندارد.');
}

// ===== ۷. ساخت CTE برای موجودیت‌های ارجاع‌شده =====
const cteParts = [];
for (const name of Object.keys(defs)) {
  if (!referenced.has(name.toLowerCase())) continue;
  const d = defs[name];
  if (d.kind === 'virtual') {
    if (!d.sql) throw new Error(`⛔ تعریف موجودیت [${name}] در کاتالوگ ناقص است.`);
    cteParts.push(`[${d.name}] AS (\n${d.sql}\n)`);
  } else {
    if (!d.source) throw new Error(`⛔ منبع موجودیت [${name}] در کاتالوگ تعریف نشده است.`);
    const cols = (d.columns || []).map(c => c.alias ? `[${c.name}] AS [${c.alias}]` : `[${c.name}]`);
    cteParts.push(`[${d.name}] AS (SELECT ${cols.join(', ')} FROM ${d.source})`);
  }
}

// ===== ۸. ادغام با WITH خود مدل =====
const prefix = 'WITH ' + cteParts.join(',\n');
const finalSql = /^\s*with\b/i.test(sql)
  ? prefix + sql.replace(/^\s*with\b/i, ',\n')
  : prefix + '\n' + sql;

return [{ json: { sql: finalSql, modelSql: sql, entities: [...referenced], understood, thinking } }];

// ===== موتور کاتالوگ: انتخاب موجودیت‌ها و ساخت prompt (با امتیاز معنایی) =====
const CFG = {
  MAX_PROMPT_CHARS: 12000,   // بودجه اندازه prompt
  MIN_SCORE:        1,       // حداقل امتیاز برای انتخاب - پس از افزودن امتیاز معنایی دوباره تنظیم کن
  CLOSURE_HOPS:     1,       // بستار روابط
  SEMANTIC_WEIGHT:  4        // سهم شباهت معنایی در امتیاز نهایی - با تست روی سوالات واقعی تنظیم شود
};

// ---------- نرمال‌سازی فارسی ----------
const norm = s => String(s == null ? '' : s)
  .replace(/‌/g, ' ')
  .replace(/[​‍-‏‪-‮﻿]/g, '')
  .replace(/[يى]/g, 'ی')
  .replace(/ك/g, 'ک')
  .replace(/[ً-ْٰ]/g, '')
  .replace(/[۰-۹]/g, d => String.fromCharCode(d.charCodeAt(0) - 0x06F0 + 48))
  .replace(/[٠-٩]/g, d => String.fromCharCode(d.charCodeAt(0) - 0x0660 + 48))
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

// ---------- شباهت کسینوسی ----------
function cosineSim(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na  += a[i] * a[i];
    nb  += b[i] * b[i];
  }
  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom > 0 ? dot / denom : 0;
}

// خواندن embedding سوال - اگر نود Embed Question خطا داده یا موجود نیست،
// به‌جای شکست کل درخواست، فقط امتیاز معنایی صفر می‌شود و امتیاز کلیدواژه‌ای کار می‌کند
let questionEmbedding = null;
try {
  const embedNode = $('Embed Question').first().json;
  questionEmbedding = embedNode.embedding || (embedNode.body && embedNode.body.embedding) || null;
} catch (e) {
  questionEmbedding = null;
}

// ---------- ۱. خواندن کاتالوگ‌ها ----------
const catalogs = $input.all()
  .map(i => i.json)
  .map(j => (j && j.entities) ? j : (j && j.data && j.data.entities) ? j.data : null)
  .filter(Boolean);

if (catalogs.length === 0) {
  throw new Error('⛔ کاتالوگ خوانده نشد. فایل‌های /data/catalog را بررسی کنید.');
}

const groups   = $('AuthCheck').first().json.groups || [];
const question = $('Webhook').first().json.body.question;
if (!question) throw new Error('⛔ سوالی دریافت نشد.');

// ---------- ۲. دسترسی: گروه AD → موجودیت‌های مجاز ----------
const groupSet = new Set(groups.map(norm));
const allowed  = new Map();

for (const cat of catalogs) {
  const perms = cat.permissions || {};
  const names = new Set();
  let all = false;
  for (const [g, list] of Object.entries(perms)) {
    if (!groupSet.has(norm(g))) continue;
    for (const n of (list || [])) {
      if (n === '*') all = true; else names.add(n);
    }
  }
  if (!all && names.size === 0) continue;
  for (const ent of (cat.entities || [])) {
    if (all || names.has(ent.name)) {
      allowed.set(ent.name, Object.assign({}, ent, { _catalog: cat }));
    }
  }
}

if (allowed.size === 0) {
  console.log('ACCESS DENIED | ' + ($('AuthCheck').first().json.email || '?')
    + ' | groups: ' + (groups.join(', ') || 'none'));
  throw new Error('⛔ شما دسترسی به این سامانه را ندارید.\n\nبرای درخواست دسترسی با واحد فناوری اطلاعات تماس بگیرید.');
}

// ---------- ۳. امتیازدهی ربط: کلیدواژه‌ای + معنایی ----------
const q = norm(question);
const qTokens = q.split(' ').filter(t => t.length >= 3);

function lexicalScoreOf(ent) {
  let score = 0;
  const contains = (text, w) => {
    const t = norm(text);
    if (t.length >= 2 && q.includes(t)) score += w;
  };
  contains(ent.name, 3);
  for (const s of (ent.synonyms_fa || [])) contains(s, 3);

  const desc = norm(ent.description_fa);
  for (const tok of qTokens) if (desc.includes(tok)) score += 0.5;

  for (const c of (ent.columns || [])) {
    if (c.exposed === false) continue;
    contains(c.alias || c.name, 1);
    for (const s of (c.synonyms_fa || [])) contains(s, 2);
  }
  return score;
}

function scoreOf(ent) {
  const lex = lexicalScoreOf(ent);

  let sem = 0;
  if (questionEmbedding && ent.embedding) {
    const sim = cosineSim(questionEmbedding, ent.embedding);   // roughly -1..1
    sem = Math.max(0, sim) * CFG.SEMANTIC_WEIGHT;
  }

  return { total: lex + sem, lex, sem };
}

const scored = [...allowed.values()]
  .map(e => {
    const s = scoreOf(e);
    return { ent: e, score: s.total, lex: s.lex, sem: s.sem };
  })
  .sort((a, b) => b.score - a.score);

// لاگ برای تنظیم SEMANTIC_WEIGHT و MIN_SCORE در فاز تست
console.log('SCORES | ' + scored.slice(0, 8)
  .map(s => `${s.ent.name}=${s.score.toFixed(2)}(lex ${s.lex.toFixed(1)} + sem ${s.sem.toFixed(1)})`)
  .join(' | '));

const scoreByName = new Map(scored.map(s => [s.ent.name, s.score]));

const selected = new Set(
  scored.filter(s => s.score >= CFG.MIN_SCORE).map(s => s.ent.name)
);

// ---------- ۴. موجودیت‌های core همیشه حاضرند ----------
for (const e of allowed.values()) if (e.core) selected.add(e.name);

if (selected.size === 0) {
  for (const s of scored.slice(0, 3)) selected.add(s.ent.name);
}

// ---------- ۵. بستار روابط ----------
const allJoins = catalogs.flatMap(c => c.joins || []);
for (let hop = 0; hop < CFG.CLOSURE_HOPS; hop++) {
  const add = [];
  for (const j of allJoins) {
    if (selected.has(j.from) && !selected.has(j.to)   && allowed.has(j.to))   add.push(j.to);
    if (selected.has(j.to)   && !selected.has(j.from) && allowed.has(j.from)) add.push(j.from);
  }
  add.forEach(n => selected.add(n));
}

// ---------- ۶. ساخت DDL و بستن بودجه ----------
const ddlOf = ent => {
  const cols = (ent.columns || []).filter(c => c.exposed !== false);
  const lines = cols.map((c, idx) => {
    const nm   = c.alias || c.name;
    const last = idx === cols.length - 1;
    const d    = c.description_fa ? `   -- ${c.description_fa}` : '';
    return `  [${nm}] ${c.type || 'nvarchar'}${last ? '' : ','}${d}`;
  });
  const head = ent.description_fa
    ? `CREATE TABLE [${ent.name}] (   -- ${ent.description_fa}`
    : `CREATE TABLE [${ent.name}] (`;
  return `${head}\n${lines.join('\n')}\n);\n`;
};

const order = [...selected].sort(
  (a, b) => (scoreByName.get(b) || 0) - (scoreByName.get(a) || 0)
);

const finalNames = [];
let schema = '', used = 0;
for (const name of order) {
  const ddl = ddlOf(allowed.get(name));
  if (used + ddl.length > CFG.MAX_PROMPT_CHARS && finalNames.length > 0) continue;
  schema += ddl + '\n';
  used += ddl.length;
  finalNames.push(name);
}

// ---------- ۷. روابط بین موجودیت‌های انتخاب‌شده ----------
const nameSet = new Set(finalNames);
const seenRel = new Set();
let rels = '';
for (const j of allJoins) {
  if (!nameSet.has(j.from) || !nameSet.has(j.to)) continue;
  const line = `-- [${j.from}].[${j.from_column}] = [${j.to}].[${j.to_column}]`;
  if (seenRel.has(line)) continue;
  seenRel.add(line);
  rels += line + '\n';
}

// ---------- ۸. راهنماها و مثال‌ها ----------
const usedCatalogs = [...new Set(finalNames.map(n => allowed.get(n)._catalog))];
const hints    = usedCatalogs.flatMap(c => c.hints_fa || []);
const examples = usedCatalogs.flatMap(c => c.examples || []).slice(0, 3);

// ---------- ۹. ساخت prompt ----------
const prompt = `You are a Microsoft SQL Server (T-SQL) expert.

Your response must have EXACTLY this shape and nothing else:
UNDERSTOOD: <one concise English sentence restating what the question is asking for - always in English, even though the question may be in Persian>
SQL:
<a single T-SQL SELECT query - no markdown fences, no explanation>

RULES:
- Microsoft SQL Server. Use SELECT TOP N. NEVER use LIMIT.
- TOP comes immediately after SELECT.
- The entities below are ready-made views. Query them directly.
- Use ONLY these entities, columns and relationships. Names EXACTLY as listed, in [square brackets].
- The question may be written in Persian. Understand it, but respond only with SQL.
${hints.length ? '\nDOMAIN NOTES:\n' + hints.map(h => '- ' + h).join('\n') + '\n' : ''}
${examples.map((ex, i) => `Example ${i + 1}:\nQ: ${ex.q}\nA: ${ex.sql}`).join('\n\n')}

Available entities:
${schema}Relationships:
${rels}
Q: ${question}
A:`;

// ---------- ۱۰. خروجی ----------
const entityDefs = {};
for (const n of finalNames) {
  const e = allowed.get(n);
  entityDefs[n] = {
    name:    e.name,
    kind:    e.kind || 'table',
    source:  e.source || null,
    sql:     e.sql || null,
    columns: (e.columns || [])
      .filter(c => c.exposed !== false)
      .map(c => ({ name: c.name, alias: c.alias || null }))
  };
}

console.log('SELECTED | ' + finalNames.join(', ') + ' | promptChars=' + prompt.length
  + ' | semanticUsed=' + Boolean(questionEmbedding));

return [{
  json: {
    body: { string1: '-', string2: prompt },
    question: question,
    selectedEntities: finalNames,
    entityDefs: entityDefs,
    promptChars: prompt.length
  }
}];

const DEBUG = true;   // در زمان توسعه true کن تا متن فنی هم دیده شود

const e = $input.first().json;
let raw = (e.error && (e.error.message || e.error)) || e.message || '';
raw = String(raw).replace(/\s*\[line \d+\]\s*$/i, '').trim();

const answer = (raw.startsWith('⛔') || DEBUG)
  ? raw
  : '⛔ در پردازش درخواست شما خطایی رخ داد.\n\nلطفاً سوال را به شکل دیگری بپرسید. اگر تکرار شد با واحد فناوری اطلاعات تماس بگیرید.';

return [{ json: { answer } }];

// ===== خواندن گروه‌های AD =====
// احراز هویت در OpenWebUI انجام شده؛ اینجا فقط عضویت گروه‌ها را می‌خوانیم.
const wh = $('Webhook').first().json.body;
const identity    = (wh.email || '').trim().toLowerCase();
const displayName = wh.username || '';

if (!identity) {
  throw new Error('⛔ ایمیل کاربر دریافت نشد. ورود به OpenWebUI باید از طریق LDAP باشد.');
}

const entries = $input.all()
  .map(i => i.json)
  .filter(e => e && Object.keys(e).length > 0);

if (entries.length === 0) {
  throw new Error('⛔ کاربر در دایرکتوری یافت نشد: ' + identity);
}
if (entries.length > 1) {
  // چند رکورد برای یک ایمیل یعنی داده‌ی دایرکتوری مبهم است — نباید حدس بزنیم
  throw new Error('⛔ چند رکورد برای این کاربر در دایرکتوری یافت شد. با تیم IT تماس بگیرید.');
}

const e = entries[0];
let memberOf = e.memberOf || [];
if (typeof memberOf === 'string') memberOf = [memberOf];

const groups = memberOf
  .map(dn => (String(dn).match(/^CN=([^,]+)/i) || [])[1])
  .filter(Boolean);

return [{
  json: {
    username: e.sAMAccountName || displayName,
    email: identity,
    groups: groups
  }
}];

// ===== Build a repair prompt: send the failed SQL + the DB error back to the model =====
const errItem = $input.first().json;
const errMsg = String(
  (errItem.error && (errItem.error.message || errItem.error)) ||
  errItem.message ||
  JSON.stringify(errItem)
).slice(0, 1000);

// The SQL that actually failed. Prefer the model's raw SELECT (modelSql) over the
// CTE-wrapped version (sql) so the fix-up prompt matches the shape the model produced.
const failedSql = $('Security').first().json.modelSql || $('Security').first().json.sql || '';

// Reuse the original prompt (schema, rules, question) so the model has full context again.
const originalPrompt = $('BuildPrompt').first().json.body.string2;

const fixPrompt = `${originalPrompt}

Your previous answer was:
${failedSql}

Running it against Microsoft SQL Server failed with this error:
${errMsg}

Fix the query so it runs successfully. Reply in the exact same shape as before:
UNDERSTOOD: <English sentence>
SQL:
<the corrected T-SQL SELECT query>
Use ONLY the listed entities and columns with their exact names. No markdown fences, no other text.`;

return [{
  json: {
    body: { string1: '-', string2: fixPrompt }
  }
}];

// ===== ۱. استخراج متن پاسخ از API =====
const res = $input.first().json;

let raw = '';
if (typeof res === 'string') {
  raw = res;
} else {
  const KEYS = ['result','response','answer','text','output','message','content'];
  for (const k of KEYS) {
    if (typeof res[k] === 'string' && res[k].trim()) { raw = res[k]; break; }
  }
  if (!raw) {
    const s = Object.values(res).find(v => typeof v === 'string' && v.trim().length > 5);
    if (s) raw = s;
  }
}
if (!raw) {
  throw new Error('⛔ ساختار پاسخ API شناخته نشد: ' + JSON.stringify(res).slice(0, 300));
}

// ===== ۱ب. جدا کردن reasoning/thinking مدل (برای نمایش در OpenWebUI) =====
// سه حالت ممکن را پوشش می‌دهد: فیلد جدای thinking در JSON پاسخ backend،
// تگ‌های <think>...</think> داخل متن، یا متن آزاد قبل از پاسخ ساختاریافته.
let thinking = '';
if (typeof res === 'object' && res) {
  const THINK_KEYS = ['thinking', 'reasoning', 'reasoning_content', 'thoughts'];
  for (const k of THINK_KEYS) {
    if (typeof res[k] === 'string' && res[k].trim()) { thinking += res[k].trim() + '\n'; break; }
  }
}
const thinkTag = raw.match(/<think>([\s\S]*?)<\/think>/i);
if (thinkTag) {
  thinking += thinkTag[1].trim();
  raw = raw.replace(thinkTag[0], '').trim();
}

// ===== ۱ج. جدا کردن پاکت ساختاریافته: UNDERSTOOD: ... / SQL: ... =====
let understood = '';
const understoodMatch = raw.match(/UNDERSTOOD:\s*(.+)/i);
if (understoodMatch) understood = understoodMatch[1].trim();

const sqlMarker = raw.search(/\bSQL:\s*/i);
if (sqlMarker !== -1) {
  const leftover = raw.slice(0, sqlMarker).replace(/UNDERSTOOD:.*$/im, '').trim();
  if (leftover) thinking = (thinking ? thinking + '\n' : '') + leftover;
  raw = raw.slice(sqlMarker).replace(/^SQL:\s*/i, '').trim();
} else if (understoodMatch) {
  // مدل UNDERSTOOD: را نوشته ولی SQL: را فراموش کرده - فقط همان خط حذف شود
  raw = raw.replace(understoodMatch[0], '').trim();
}

// ===== ۲. جدا کردن SQL از متن پرحرف مدل (فالبک قبلی، بدون تغییر) =====
let sql = '';
const fence = raw.match(/```sql\s*([\s\S]*?)```/i) || raw.match(/```\s*([\s\S]*?)```/);
if (fence) {
  sql = fence[1].trim();
} else {
  const m = raw.match(/\b(select|with)\b[\s\S]*/i);
  sql = m ? m[0].trim() : raw.trim();
  sql = sql.split(/\n\s*\n/)[0].trim();
}

const SQLKW = /^\s*(select|from|where|group|order|having|join|inner|left|right|full|cross|outer|on|and|or|union|with|as|top|case|when|then|else|end|\)|,)/i;
sql = sql.split('\n')
         .filter(l => !/[؀-ۿ]/.test(l) || SQLKW.test(l) || l.includes("'"))
         .join('\n').trim();

sql = sql.replace(/;+\s*$/, '').trim();
if (!sql) {
  throw new Error('⛔ مدل نتوانست کوئری تولید کند. لطفاً سوال را واضح‌تر بپرسید.');
}

// ===== ۳. تور ایمنی: LIMIT n → TOP n =====
const lim = sql.match(/\blimit\s+(\d+)\s*;?\s*$/i);
if (lim) {
  sql = sql.replace(/\blimit\s+\d+\s*;?\s*$/i, '').trim();
  if (!/^\s*select\s+top\b/i.test(sql)) {
    sql = sql.replace(/^\s*select\b/i, `SELECT TOP ${lim[1]}`);
  }
}

// ===== ۴. لایه امنیتی =====
if (!/^\s*(select|with)\b/i.test(sql)) {
  throw new Error('⛔ عملیات مجاز نیست: فقط SELECT.');
}
const blocked = [
  /\binsert\b/i, /\bupdate\b/i, /\bdelete\b/i, /\bdrop\b/i,
  /\btruncate\b/i, /\balter\b/i, /\bcreate\b/i, /\bmerge\b/i,
  /\bexec\b/i, /\bexecute\b/i, /\bgrant\b/i, /\brevoke\b/i,
  /\bbackup\b/i, /\brestore\b/i, /\bshutdown\b/i, /\bwaitfor\b/i,
  /\binto\b/i, /\bxp_\w+/i, /\bsp_\w+/i, /openrowset/i, /opendatasource/i
];
for (const p of blocked) {
  if (p.test(sql)) throw new Error('⛔ عملیات مجاز نیست: دستور غیرمجاز.');
}
if (sql.includes(';') || sql.includes('--') || sql.includes('/*')) {
  throw new Error('⛔ عملیات مجاز نیست: کاراکتر غیرمجاز.');
}

// ===== ۵. سقف ردیف اجباری =====
// اولین SELECT در عمق پرانتز صفر — برای کوئری‌های WITH هم کار می‌کند
function injectTop(s, n) {
  if (/^\s*select\s+top\b/i.test(s)) return s;
  if (/^\s*select\b/i.test(s)) return s.replace(/^\s*select\b/i, `SELECT TOP ${n}`);
  let depth = 0, quote = null;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) { if (ch === quote) quote = null; continue; }
    if (ch === "'" || ch === '"') { quote = ch; continue; }
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (depth === 0 && (ch === 's' || ch === 'S') && /^select\b/i.test(s.slice(i))) {
      const before = i === 0 ? ' ' : s[i - 1];
      if (/[A-Za-z0-9_\]]/.test(before)) continue;
      if (/^select\s+top\b/i.test(s.slice(i))) return s;
      return s.slice(0, i) + `SELECT TOP ${n}` + s.slice(i + 6);
    }
  }
  return s;
}
sql = injectTop(sql, 200);

// ===== ۶. اعتبارسنجی: فقط موجودیت‌های انتخاب‌شده =====
// این مرحله باید قبل از چسباندن CTEها اجرا شود — بازرسی روی خروجی مدل، نه SQL نهایی
const defs = $('BuildPrompt').first().json.entityDefs || {};
const allowedNames = new Set(Object.keys(defs).map(n => n.toLowerCase()));

const cteNames = new Set();
const cteRe = /(?:\bwith\b|,)\s*\[?([A-Za-z0-9_]+)\]?\s+as\s*\(/gi;
let cm;
while ((cm = cteRe.exec(sql)) !== null) cteNames.add(cm[1].toLowerCase());

const referenced = new Set();
const refRe = /\b(?:from|join)\s+((?:\[?[A-Za-z0-9_]+\]?\.){0,2}\[?[A-Za-z0-9_]+\]?)/gi;
let mm;
while ((mm = refRe.exec(sql)) !== null) {
  const parts = mm[1].split('.');
  const nm = parts[parts.length - 1].replace(/[\[\]]/g, '').toLowerCase();
  if (cteNames.has(nm)) continue;                 // CTE خود مدل
  if (!allowedNames.has(nm)) {
    throw new Error('⛔ اجرای این دستور خارج از حیطه دسترسی شماست.');
  }
  referenced.add(nm);
}

if (referenced.size === 0) {
  throw new Error('⛔ کوئری تولیدشده به هیچ موجودیت معتبری ارجاع ندارد.');
}

// ===== ۷. ساخت CTE برای موجودیت‌های ارجاع‌شده =====
// هم table و هم virtual به CTE تبدیل می‌شوند: نگاشت نام یکدست می‌شود
// و ستون‌های exposed:false واقعاً غیرقابل دسترس می‌مانند
const cteParts = [];
for (const name of Object.keys(defs)) {
  if (!referenced.has(name.toLowerCase())) continue;
  const d = defs[name];
  if (d.kind === 'virtual') {
    if (!d.sql) throw new Error(`⛔ تعریف موجودیت [${name}] در کاتالوگ ناقص است.`);
    cteParts.push(`[${d.name}] AS (\n${d.sql}\n)`);
  } else {
    if (!d.source) throw new Error(`⛔ منبع موجودیت [${name}] در کاتالوگ تعریف نشده است.`);
    const cols = (d.columns || []).map(c => c.alias ? `[${c.name}] AS [${c.alias}]` : `[${c.name}]`);
    cteParts.push(`[${d.name}] AS (SELECT ${cols.join(', ')} FROM ${d.source})`);
  }
}

// ===== ۸. ادغام با WITH خود مدل =====
// لیست CTEها با کاما جدا می‌شود، پس WITH مدل به کاما تبدیل می‌شود
const prefix = 'WITH ' + cteParts.join(',\n');
const finalSql = /^\s*with\b/i.test(sql)
  ? prefix + sql.replace(/^\s*with\b/i, ',\n')
  : prefix + '\n' + sql;

return [{ json: { sql: finalSql, modelSql: sql, entities: [...referenced], understood, thinking } }];
